    final POP3MessageInfo[] msg = pop3Client.listMessages();
    // removed other assertion

    for (int i = msg.length; i > 0; i--)
    {
        reportedSize = msg[i - 1].size;
        final Reader r = pop3Client.retrieveMessage(i);
        assertNotNull(r);
}
