mut_method_definition:
public Reader retrieveMessage(final int messageId) throws IOException
    {
        if (getState() != TRANSACTION_STATE) {
            return null;
        }
        if (sendCommand(POP3Command.RETR, Integer.toString(messageId)) != POP3Reply.OK) {
            return null;
        }

        return new DotTerminatedMessageReader(reader);
    }

test_prefix:
public void testRetrieveMessageOnFullMailbox_3_oe() throws Exception
{
    reset();
    connect();
    login();
    int reportedSize = 0;
    int actualSize = 0;

    final POP3MessageInfo[] msg = pop3Client.listMessages();
    // removed other assertion

    for (int i = msg.length; i > 0; i--)
    {
        reportedSize = msg[i - 1].size;
        final Reader r = pop3Client.retrieveMessage(i);
        // removed other assertion

        int delaycount = 0;
        if (!r.ready())
        {
            //Give the reader time to get the message
            //from the server
            Thread.sleep(500);
            delaycount++;
            //but don't wait too long
            if (delaycount == 4)
            {
                break;
            }
        }
        while(r.ready())
        {
            r.read();
            actualSize++;
        }
        //Due to variations in line termination
        //on different platforms, the actual
        //size may vary slightly.  On Win2KPro, the
        //actual size is 2 bytes larger than the reported
        //size.
        assertTrue(actualSize >= reportedSize);
}
}

mut_method_definition:
@Override
    public int read() throws IOException
    {
        final int ch;

        if (status == LAST_WAS_NL)
        {
            status = NOTHING_SPECIAL;
            return '\n';
        }

        ch = in.read();

        switch (ch)
        {
        case '\r':
            status = LAST_WAS_CR;
            return '\r';
        case '\n':
            if (status != LAST_WAS_CR)
            {
                status = LAST_WAS_NL;
                return '\r';
            }
            //$FALL-THROUGH$
        default:
            status = NOTHING_SPECIAL;
            return ch;
        }
        // statement not reached
        //return ch;
    }

